import React, { useContext, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import { FiShoppingCart, FiLogOut, FiUser, FiGrid, FiBox, FiActivity } from 'react-icons/fi';
import './Dashboard.css';

const Dashboard = () => {
    const { user, stores, activeStore, changeStore, logout, getAuthHeaders } = useContext(AuthContext);
    const navigate = useNavigate();
    const [cartSummary, setCartSummary] = useState({ products: [], total_bill: 0 });
    const [products, setProducts] = useState([]);
    const [loadingData, setLoadingData] = useState(true);

    const activeStoreObj = stores.find(s => s.id === activeStore) || stores[0];

    useEffect(() => {
        if (!activeStore) return;
        setLoadingData(true);
        Promise.all([
            fetch('http://localhost:5000/api/cart', { headers: getAuthHeaders() }).then(r => r.json()).catch(() => null),
            fetch('http://localhost:5000/api/products', { headers: getAuthHeaders() }).then(r => r.json()).catch(() => null),
        ]).then(([cartData, productsData]) => {
            if (cartData?.success) setCartSummary(cartData);
            if (productsData?.success) setProducts(productsData.products || []);
        }).finally(() => setLoadingData(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [activeStore]);

    const handleLogout = () => {
        logout();
        navigate('/login');
    };

    return (
        <div className="dashboard-root">
            {/* Top Navigation Bar */}
            <nav className="dash-navbar">
                <div className="dash-brand">
                    <span className="dash-brand-icon">🛒</span>
                    <span className="dash-brand-name">SmartRetail AI</span>
                </div>

                <div className="dash-nav-center">
                    {stores.length > 0 && (
                        <div className="dash-store-picker">
                            <FiGrid className="dash-store-icon" />
                            <select
                                value={activeStore || ''}
                                onChange={(e) => changeStore(parseInt(e.target.value))}
                                className="dash-store-select"
                            >
                                {stores.map(s => (
                                    <option key={s.id} value={s.id}>
                                        {s.name}
                                    </option>
                                ))}
                            </select>
                        </div>
                    )}
                </div>

                <div className="dash-nav-right">
                    <div className="dash-user-chip">
                        <div className="dash-avatar">
                            {user?.full_name ? user.full_name[0].toUpperCase() : 'U'}
                        </div>
                        <span className="dash-username">{user?.full_name || 'User'}</span>
                    </div>
                    <button className="dash-logout-btn" onClick={handleLogout}>
                        <FiLogOut />
                        <span>Logout</span>
                    </button>
                </div>
            </nav>

            {/* Main Content */}
            <main className="dash-main">
                {/* Welcome Banner */}
                <div className="dash-welcome-banner">
                    <div className="dash-welcome-text">
                        <h1>Welcome back, {user?.full_name?.split(' ')[0] || 'there'} 👋</h1>
                        <p>
                            Managing <strong>{activeStoreObj?.name || 'your store'}</strong>
                            {activeStoreObj?.role && <span className="dash-role-badge">{activeStoreObj.role}</span>}
                        </p>
                    </div>
                    <button
                        className="dash-scan-cta"
                        onClick={() => navigate('/checkout')}
                    >
                        <FiActivity />
                        Start AI Scanning Session
                    </button>
                </div>

                {/* Stats Row */}
                <div className="dash-stats-grid">
                    <div className="dash-stat-card">
                        <div className="dash-stat-icon" style={{ background: 'rgba(99,102,241,0.15)', color: '#818cf8' }}>
                            <FiBox />
                        </div>
                        <div>
                            <div className="dash-stat-value">{loadingData ? '...' : products.length}</div>
                            <div className="dash-stat-label">Products in Catalogue</div>
                        </div>
                    </div>

                    <div className="dash-stat-card">
                        <div className="dash-stat-icon" style={{ background: 'rgba(16,185,129,0.15)', color: '#34d399' }}>
                            <FiShoppingCart />
                        </div>
                        <div>
                            <div className="dash-stat-value">{loadingData ? '...' : cartSummary.products.length}</div>
                            <div className="dash-stat-label">Items in Active Cart</div>
                        </div>
                    </div>

                    <div className="dash-stat-card">
                        <div className="dash-stat-icon" style={{ background: 'rgba(234,179,8,0.15)', color: '#fbbf24' }}>
                            <FiUser />
                        </div>
                        <div>
                            <div className="dash-stat-value">{stores.length}</div>
                            <div className="dash-stat-label">Stores Accessible</div>
                        </div>
                    </div>
                </div>

                {/* Active Cart Preview */}
                {cartSummary.products.length > 0 && (
                    <div className="dash-cart-preview">
                        <div className="dash-section-header">
                            <h2>🛒 Active Cart</h2>
                            <button className="dash-view-all" onClick={() => navigate('/checkout')}>
                                Go to Checkout →
                            </button>
                        </div>
                        <div className="dash-cart-table-wrap">
                            <table className="dash-cart-table">
                                <thead>
                                    <tr>
                                        <th>Product</th>
                                        <th>Qty</th>
                                        <th>Unit Price</th>
                                        <th>Total</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {cartSummary.products.map((p, i) => (
                                        <tr key={i}>
                                            <td>{p.name}</td>
                                            <td>{p.quantity}</td>
                                            <td>₹{Number(p.price).toFixed(2)}</td>
                                            <td style={{ color: '#818cf8', fontWeight: 700 }}>
                                                ₹{(p.price * p.quantity).toFixed(2)}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                                <tfoot>
                                    <tr>
                                        <td colSpan="3" style={{ textAlign: 'right', fontWeight: 700, color: '#94a3b8' }}>Total Bill</td>
                                        <td style={{ color: '#34d399', fontWeight: 800 }}>₹{Number(cartSummary.total_bill).toFixed(2)}</td>
                                    </tr>
                                </tfoot>
                            </table>
                        </div>
                    </div>
                )}

                {/* Product Catalogue Preview */}
                {products.length > 0 && (
                    <div className="dash-products-section">
                        <div className="dash-section-header">
                            <h2>📦 Store Catalogue</h2>
                            <span className="dash-product-count">{products.length} products</span>
                        </div>
                        <div className="dash-product-grid">
                            {products.slice(0, 6).map((p, i) => (
                                <div key={i} className="dash-product-card">
                                    <div className="dash-product-emoji">🏷️</div>
                                    <div className="dash-product-name">{p.name}</div>
                                    <div className="dash-product-price">₹{Number(p.price).toFixed(2)}</div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {/* Quick Actions */}
                <div className="dash-quick-actions">
                    <h2>Quick Actions</h2>
                    <div className="dash-action-grid">
                        <button className="dash-action-card primary" onClick={() => navigate('/checkout')}>
                            <FiActivity className="dash-action-icon" />
                            <span>AI Checkout Scanner</span>
                            <small>Upload video & detect products</small>
                        </button>
                    </div>
                </div>
            </main>
        </div>
    );
};

export default Dashboard;
